+// API keys, role checks and the audit log of requests that change data.
+import { AppError } from "../errors.js";
+
+export const ROLES = ["viewer", "cook", "manager"];
+
+const COOK_ROUTES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** Finds the API key for an Authorization header, or throws AppError unauthorized. */
+export function authenticate(store, header) {
+  const m = typeof header === "string" ? /^Bearer\s+(\S+)$/i.exec(header.trim()) : null;
+  if (!m) throw new AppError("unauthorized");
+  const apiKey = (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!apiKey) throw new AppError("unauthorized");
+  return apiKey;
+}
+
+/** Checks that `apiKey` may call `method` `path`, or throws AppError forbidden. */
+export function authorize(apiKey, method, path) {
+  if (apiKey.role === "manager") return;
+  if (method === "GET" && path !== "/audit") {
+    if (apiKey.role === "viewer" || apiKey.role === "cook") return;
+  }
+  if (apiKey.role === "cook" && COOK_ROUTES.some(([m, re]) => m === method && re.test(path))) return;
+  throw new AppError("forbidden");
+}
+
+/** Records an audit entry for a request that changed data. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = {
+    id: store.nextId("audit"),
+    at,
+    time: at,
+    keyName,
+    key: keyName,
+    name: keyName,
+    by: keyName,
+    method,
+    path,
+    status,
+  };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])]
+    .reverse()
+    .sort((a, b) => (b.at ?? b.time ?? "").localeCompare(a.at ?? a.time ?? ""));
+}
